document.getElementById("Formproduct").addEventListener("submit",async e=>{e.preventDefault(),e.stopImmediatePropagation();const t=e.target;try{const o=await fetch(t.dataset.url,{method:"POST",headers:{"X-CSRF-TOKEN":document.querySelector('meta[name="csrf-token"]').getAttribute("content"),Accept:"text/html"},body:new FormData(t)});if(o.ok){const r=await o.text();document.getElementById("productBody").insertAdjacentHTML("beforeend",r),t.reset();const n=document.getElementById("hs-scroll-inside-body-modal");n&&typeof HSOverlay<"u"&&HSOverlay.close(n),console.log("product added")}}catch(o){console.error("Error details:",o)}});let a;document.getElementById("searchInput").addEventListener("input",async e=>{clearTimeout(a),a=setTimeout(async()=>{const t=e.target.dataset.url,r=await(await fetch(`${t}?search=${e.target.value}`)).text();document.getElementById("productBody").innerHTML=new DOMParser().parseFromString(r,"text/html").getElementById("productBody").innerHTML},300)});
